buy_code:
# ================================
#  오후 되돌림 (min 풀세션) — 눌림 후 재반등
# ================================
매수 = True

if not (관심종목 == 1):
    매수 = False
elif not ({entry_start} <= 시분초 < {entry_end}):
    매수 = False
elif not (데이터길이 > 60):
    매수 = False
elif not (1000 < 현재가 <= 50000):
    매수 = False
elif not ({rate_min} <= 등락율 <= {rate_max}):
    매수 = False
elif not (시가총액 < {cap_max}):
    매수 = False
elif 라운드피겨위5호가이내:
    매수 = False
elif not (구간고가대비현재가등락율(60) <= -{pull_min}):
    매수 = False
elif not (현재가 >= 이동평균({ma_len}) * (1 - {ma_band} / 100)):
    매수 = False
elif not (현재가 <= 이동평균({ma_len}) * (1 + {ma_band} / 100)):
    매수 = False
elif not (현재가 > 현재가N(1)):
    매수 = False
elif not (분당거래대금 > 분당거래대금평균(30) * {vol_rebound}):
    매수 = False
elif not (체결강도 >= {strength_min}):
    매수 = False

if 매수:
    self.Buy()

sell_code:
# ================================
#  오후 되돌림 매도 (min) — 보유시간 단위: 분
# ================================
매도 = False

if 등락율 > 29.5:
    매도 = True
elif 수익률 >= {take_hard}:
    매도 = True
elif 수익률 <= {stop_hard}:
    매도 = True
elif 최고수익률 > {trail_start} and 최고수익률 * {trail_keep} >= 수익률:
    매도 = True
elif 보유시간 > {max_hold_min}:
    매도 = True
elif 시분초 >= 151500:
    매도 = True

if 매도:
    self.Sell()
